import fs from "node:fs";
import path from "node:path";

const root = process.cwd();
const sourceFiles = [
  "src/utils.js",
  "src/difficulty.js",
  "src/game-state.js",
  "src/scenes.js",
  "src/save.js",
  "src/audio.js",
  "src/renderer.js",
  "src/main.js",
];

function stripModuleSyntax(source, file) {
  return source
    .replace(/^\s*import\s+[\s\S]*?from\s+["'][^"']+["'];?\s*$/gm, "")
    .replace(/^\s*import\s+["'][^"']+["'];?\s*$/gm, "")
    .replace(/\bexport\s+(?=(const|let|var|function|class)\s+)/g, "")
    .replace(/^\s*export\s*\{[\s\S]*?\};?\s*$/gm, "")
    .trim()
    .concat(`\n\n/* end ${file} */\n`);
}

const chunks = sourceFiles.map((file) => {
  const source = fs.readFileSync(path.join(root, file), "utf8");
  return `/* begin ${file} */\n${stripModuleSyntax(source, file)}`;
});

const banner = `// Generated by scripts/build-file-bundle.mjs.
// This bundle lets index.html run from file:// without an HTTP server.
// Edit src/*.js, then run npm run build:file to refresh this file.
`;

const output = `${banner}\n(() => {\n"use strict";\n\n${chunks.join("\n")}\n})();\n`;
const outputPath = path.join(root, "dist", "grey-tide-standalone.js");

fs.mkdirSync(path.dirname(outputPath), { recursive: true });
fs.writeFileSync(outputPath, output, "utf8");
console.log(`Wrote ${path.relative(root, outputPath)}`);
